39	/** Spannweite (min/max des Medians Total) über die Kantone eines Jahrs und einer Kategorie. */
40	export function spannweite(jahr, kategorie) {
41	  const werte = kantonsWerte(jahr, kategorie).filter((x) => x.total != null);
42	  if (!werte.length) return null;
43	  let min = werte[0];
44	  let max = werte[0];
45	  for (const x of werte) {
46	    if (x.total < min.total) min = x;
47	    if (x.total > max.total) max = x;
48	  }
49	  return { min, max };
50	}
