52	/** Veränderung des Kanton-Medians (Total) vom ersten zum letzten Tarifjahr, je Kanton (abk → {von, nach, delta}). */
53	export function veraenderung(kategorie) {
54	  const [vonJahr, nachJahr] = [ATLAS_JAHRE[0], ATLAS_JAHRE[ATLAS_JAHRE.length - 1]];
55	  const von = new Map(kantonsWerte(vonJahr, kategorie).map((x) => [x.abk, x.total]));
56	  const liste = [];
57	  for (const x of kantonsWerte(nachJahr, kategorie)) {
58	    const alt = von.get(x.abk);
59	    if (alt == null || x.total == null) continue;
60	    liste.push({ abk: x.abk, name: x.name, von: alt, nach: x.total, delta: x.total - alt });
61	  }
62	  return liste;
63	}
